                                            io.out.emit(at, ModbusPduEvent::End { frame: event_frame, reason: reason, length_ok: length_ok, supported: self.known, valid: (self.known && (length_ok && (self.crc_ok && ((!self.partial) && (reason == EndReason::Complete))))) }).await;
                                            self.clear();
